import json
import sys
x = json.load(sys.stdin)
answer = x["artifact"]["answer"]
errors = []
begin_spec = "BEGIN_SHOT_SPEC_JSON\n"
end_spec = "\nEND_SHOT_SPEC_JSON"
begin_script = "BEGIN_BLENDER_SCRIPT\n"
end_script = "\nEND_BLENDER_SCRIPT"
if begin_spec not in answer or end_spec not in answer or begin_script not in answer or end_script not in answer:
    errors.append("required artifact markers")
else:
    spec_text = answer.split(begin_spec, 1)[1].split(end_spec, 1)[0]
    script = answer.split(begin_script, 1)[1].split(end_script, 1)[0]
    try:
        spec = json.loads(spec_text)
    except ValueError:
        spec = {}
        errors.append("spec JSON parse")
    if spec.get("schema_version") != "uc1.blender-blocking.v1": errors.append("schema version")
    if spec.get("api_target") != "Blender 5.2 Python API": errors.append("API target")
    if spec.get("fps") != 24: errors.append("fps")
    shots = spec.get("shots", [])
    if len(shots) != 3: errors.append("three shots")
    else:
        exact = [("S01_APPROACH",1,96,28.0),("S02_REVEAL",97,168,50.0),("S03_RETREAT",169,240,35.0)]
        for index, item in enumerate(exact):
            shot = shots[index]
            camera = shot.get("camera", {})
            if (shot.get("id"),shot.get("frame_start"),shot.get("frame_end"),camera.get("lens_mm")) != item:
                errors.append("shot " + str(index + 1) + " exact timing/lens")
        if any(motion.get("subject") == "crate" for shot in shots for motion in shot.get("motion", [])):
            errors.append("crate motion")
    for token in ("import bpy", "mathutils", "bpy.ops.mesh.primitive_cube_add", "bpy.ops.object.camera_add", "keyframe_insert", "SHOT_SPEC"):
        if token not in script: errors.append("script token " + token)
    for token in ("import os", "import pathlib", "import socket", "import requests", "open(", "exec(", "eval("):
        if token in script: errors.append("forbidden script token " + token)
value = not errors
print(json.dumps({"relation_id":"pilot-result","value":value,"derivation":"Structural marker/spec/token check only; errors=" + ", ".join(errors) + ". Standalone AST/API verification and fallible review remain required before conformance."}))
